import{_ as o,l as n,o as e,c as s,v as t,p as l,x as r,d,i as E,S as D}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"天气与电力衍生","description":"","frontmatter":{"title":"天气与电力衍生","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/weather-power-derivatives.md","filePath":"quant/weather-power-derivatives.md","lastUpdated":1789023840000}'),p={name:"quant/weather-power-derivatives.md"};function h(B,a,m,c,_,A){const i=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="天气与电力衍生" tabindex="-1">天气与电力衍生 <a class="header-anchor" href="#天气与电力衍生" aria-label="Permalink to &quot;天气与电力衍生&quot;">​</a></h1><div class="epigraph"><p>HDD 与 CDD 是温度对阈值的积分，不是可储存商品的期货价格；电力几乎不能库存，尖峰使对数正态成为差的第一近似。</p><footer>—— Geman, Commodities and Commodity Derivatives 中的电力与天气章；天气衍生见 Jewson 与 Brix 对 HDD 的精算处理</footer></div><p><a href="/quant/commodity-options-seasonality">上一课</a>还在可储存商品的期货期权。天气与电力的缺口是<strong>不可储或几乎不可储</strong>：温度指数没有便利收益与库存套利，电力现货有极端尖峰与负价。本课写 HDD/CDD、天气期权、以及电力远期/期权为何不能套用 WTI 的 Black-76 习惯。后课通胀回到可金融化的 CPI。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>天气衍生：支付是某站、某季的 HDD \\(\\sum\\max(T_{\\mathrm{ref}}-T_d,0)\\) 或 CDD 对执行值的差。标的不是交易的期货曲线（除非有 CME 天气期货），对冲用的是相关商品（天然气）或再保险，而不是 Delta 到「温度期货」的完整复制。问题是定价更接近精算：历史温度、趋势（气候）、以及与能源负荷的相关，而不是 GK 式的风险中性完备市场。硬套 BSM 隐波，会把不可对冲的基差藏进 \\(\\sigma\\)。</p><p>电力：日前/实时、节点电价、容量与阻塞。远期是分月、分峰谷的合约。期权在尖峰月对虚值看涨极度昂贵，负电价使看跌也非标准。库存套利几乎不存在，远期曲线可以剧烈 backwardation 而不被现货交易抹平。</p><h3 id="完备市场假设先坏掉" tabindex="-1">完备市场假设先坏掉 <a class="header-anchor" href="#完备市场假设先坏掉" aria-label="Permalink to &quot;完备市场假设先坏掉&quot;">​</a></h3><p>股权与 FX 课默认可以用标的对冲。温度不能存，也不能无摩擦交易。风险中性测度不唯一，市价来自再保供给与能源商的对冲需求。报告应把「精算期望 + 风险载荷」与「若存在液体期货则 Black」分开，不要混成一个公式。</p><p><span class="marginnote">电力尖峰可用带跳或机制转换的现货模型，再积分到月度远期。用年化 80% 的 GBM 去拟合尖峰月，尾部仍然不够，还会把非尖峰月估贵。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>天气：去趋势的历史模拟或温度的 Ornstein–Uhlenbeck + 季节，支付在物理测度下取期望，再加载荷；若有交易所期货，用其价格锚定期望，期权用残差波动。电力：分合约（峰/谷/月）的远期曲线，现货模型校准到远期与历史尖峰，期权用模拟。负价用移位或截断分布。对冲：电力用对应节点与时段的远期；天气用相关能源与地理基差限额。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不可储意味着现货可以与「合理」的远期长期脱节，尖峰是约束（容量）而不是扩散噪声。HDD 是阈值积分，凸性在冷冬，与天然气看涨相关但不等于天然气期权。把天气当天然气的 quanto，相关不稳定（暖冬可以同时压气价与 HDD）。</p>',13)),(e(),l(D,null,{default:r(()=>[E(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Temp%5B%22%E6%B8%A9%E5%BA%A6%E8%B7%AF%E5%BE%84%20%E5%AD%A3%E8%8A%82%E5%8A%A0%E8%B6%8B%E5%8A%BF%22%5D%20--%3E%20HDD%5B%22HDD%20CDD%20%E7%A7%AF%E5%88%86%22%5D%0A%20%20HDD%20--%3E%20Act%5B%22%E7%B2%BE%E7%AE%97%E6%9C%9F%E6%9C%9B%E5%8A%A0%E8%BD%BD%E8%8D%B7%22%5D%0A%20%20Pwr%5B%22%E4%B8%8D%E5%8F%AF%E5%AD%98%E7%94%B5%E5%8A%9B%22%5D%20--%3E%20Spike%5B%22%E5%B0%96%E5%B3%B0%E4%B8%8E%E8%B4%9F%E4%BB%B7%22%5D%0A%20%20Spike%20--%3E%20Fwd%5B%22%E5%88%86%E6%97%B6%E8%BF%9C%E6%9C%9F%22%5D%0A%20%20Fwd%20--%3E%20Opt%5B%22%E6%9C%9F%E6%9D%83%E6%A8%A1%E6%8B%9F%20%E9%9D%9E%20GBM%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>气候趋势使历史均值偏低或偏高，纯历史模拟有偏差。地理基差（机场站 vs 负荷区）可以吞掉整份天气期权的价值。电力市场规则（价格帽、稀缺定价）改变尾部，模型必须跟规则版本。本课不写如何在节点市场做物理交割套利。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>天气衍生是指数精算加或不加期货锚定，不是完备市场 BSM。</li><li>电力几乎不可储，尖峰与负价要求分时远期与跳/机制模型。</li><li>与天然气的相关是对冲工具，不是定价恒等式。</li><li>出处：Geman 对电力与商品的论述；Jewson and Brix, <em>Weather Derivative Valuation</em>。</li></ul>',4))])}const q=o(p,[["render",h]]);export{f as __pageData,q as default};
